import pLimit from 'p-limit';

const dbLimit = pLimit(8);            // one limiter per dependency

app.get('/rows', async (req, res) => {
  if (dbLimit.pendingCount > 64) return res.status(503).end();  // bound the queue
  const rows = await dbLimit(() => db.query(req.sql, { signal: req.signal }));
  res.json(rows);
});

import http from 'node:http';

const dbAgent = new http.Agent({ maxSockets: 8, maxFreeSockets: 8 });

const req = http.request({
  host: 'db.internal', agent: dbAgent, path: '/query',
  timeout: 2000,                     // a queued request must not wait forever
}, res => collect(res));

